  fs.mkdirSync(backup,{recursive:true,mode:0o700});
  fs.writeFileSync(path.join(backup,'changed-files.json'),JSON.stringify(changed.map(f=>({path:f.relative,wasNew:f.old===null})),null,2));
  for(const item of changed){fs.mkdirSync(path.dirname(item.target),{recursive:true});const temporary=item.target+'.scan-fix-tmp';fs.writeFileSync(temporary,item.next);fs.renameSync(temporary,item.target);}
  console.log('Installed the Gmail scan fix ('+changed.length+' source/test/documentation files).');
